#!/bin/bash
# Watchdog script for Docker container resource monitoring
# Enforces FR-012, SC-004, SC-005
# Generated by T009 implementation

CONTAINER_NAME="${1:-project_container}"
CPU_LIMIT_HOURS=6
RAM_LIMIT_GB=7
CHECK_INTERVAL=10 # seconds

echo "Starting watchdog for container: $CONTAINER_NAME"
echo "Limits: CPU=${CPU_LIMIT_HOURS}h, RAM=${RAM_LIMIT_GB}GB"

if ! command -v docker &> /dev/null; then
    echo "Error: Docker is not installed or not in PATH."
    exit 1
fi

if ! command -v bc &> /dev/null; then
    echo "Error: 'bc' is required for floating point arithmetic. Please install it."
    exit 1
fi

while true; do
    if ! docker inspect -f '{{.State.Running}}' "$CONTAINER_NAME" 2>/dev/null | grep -q true; then
        echo "Container stopped or not found. Exiting watchdog."
        exit 0
    fi

    # Get CPU usage (percentage) and Memory usage
    # docker stats --no-stream returns: CONTAINER ID, NAME, CPU %, MEM USAGE, ...
    STATS=$(docker stats --no-stream --format "{{.CPUPerc}} {{.MemUsage}}" "$CONTAINER_NAME")
    
    if [ -z "$STATS" ]; then
        echo "Error: Could not fetch stats for container."
        exit 1
    fi

    CPU_PCT=$(echo "$STATS" | awk '{print $1}' | tr -d '%')
    MEM_USAGE=$(echo "$STATS" | awk '{print $2}') # e.g., "2.5GiB"

    # Parse RAM (convert GiB/MiB to GB)
    MEM_VAL=$(echo "$MEM_USAGE" | grep -oP '^[0-9.]+')
    MEM_UNIT=$(echo "$MEM_USAGE" | grep -oP '[A-Za-z]+$')

    CURRENT_GB=0
    if [[ "$MEM_UNIT" == "GiB" ]]; then
        CURRENT_GB=$MEM_VAL
    elif [[ "$MEM_UNIT" == "MiB" ]]; then
        CURRENT_GB=$(echo "$MEM_VAL / 1024" | bc)
    elif [[ "$MEM_UNIT" == "KiB" ]]; then
        CURRENT_GB=$(echo "$MEM_VAL / 1048576" | bc)
    fi

    # Check RAM limit
    if (( $(echo "$CURRENT_GB > $RAM_LIMIT_GB" | bc -l) )); then
        echo "WARNING: RAM limit exceeded ($CURRENT_GB > $RAM_LIMIT_GB). Killing container."
        docker stop "$CONTAINER_NAME"
        exit 1
    fi

    # Note: CPU limit in Docker stats is percentage of total cores.
    # A simple percentage check isn't enough for "6 hours" total usage.
    # The Python wrapper (src/utils.py) handles the cumulative CPU hour check.
    # This script focuses on hard RAM caps and immediate CPU spikes if needed.
    # For now, we rely on the Python enforcement for CPU hours.

    sleep $CHECK_INTERVAL
done